#include "(CurrentProject)/js/personaliza/personaWizard.js"

// ----------------------------------
// Cargar objetos en combobox
// ----------------------------------

// Atrapar el subformulario donde están los controles
var formularioPadre = theRoot.dataView();
var separador = formularioPadre.control("SEP");
var formulario = separador.form("sygemat_corralon_app/PRS_MEN_W_ICO_TXT");

// Leer el proyecto seleccionado
var controlProyecto = formulario.control("ICO_PRY");
if (controlProyecto)
{
	var proyectoInfo = theApp.projectInfo(controlProyecto.itemData(controlProyecto.currentIndex));
};

// Cargar formularios en combobox
var objetosInfo = getObjetosProyectoTipoInfo(proyectoInfo, VObjectInfo.TypePicture);
var controlObjeto = formulario.control("ICO_OBJ_ID");
if (controlObjeto)
{
	// Se limpia el contenido antes de añadir el nuevo
	controlObjeto.clear();

	// Se añaden los formularios del proyecto seleccionado
	for(numObjeto in objetosInfo)
	{
		controlObjeto.addItem(objetosInfo[numObjeto].id() + "  (" + objetosInfo[numObjeto].name() + ")", objetosInfo[numObjeto].id());
	};

	controlObjeto.setCurrentIndex(controlObjeto.findData(theRegisterIn.fieldToString("ICO_OBJ_ID")));
};

#include "(CurrentProject)/js/personaliza/personaWizard.js"

// ------------------------------------
