		controlProyecto.addItem(proyectosInfo[numProyecto].name(), proyectosInfo[numProyecto].alias());
	};

	controlProyecto.setCurrentIndex(controlProyecto.findData(theRegisterIn.fieldToString("ICO_PRY")));
};

