importClass("VImage");

// -------------------------------------------------------------------------------------------------------------------------------------
// Refrescar el icono configurado o en su defecto se muestra el contenido del objeto dibujo configurado en el control
// -------------------------------------------------------------------------------------------------------------------------------------

// Leer el objeto dibujo seleccionado
var icono = new VImage();
var iconoIdRef = theRegisterIn.fieldToString("ICO_ID_REF");

if (iconoIdRef != "" ) {
	icono.loadResource(iconoIdRef);
	if (icono) {
		// Aplicamos el icono al objeto dibujo
		var formularioPadre = theRoot.dataView();
		var separador = formularioPadre.control("SEP");
		var formulario = separador.form("sygemat_corralon_app/PRS_MEN_W_ICO_TXT");
		var control = formulario.control("ICO");
		control.setImage(icono);
	};
};
